import re
async def g(q,pats,w=200,n=8):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        c=x['content']
        for p in pats:
            for m in list(re.finditer(p,c))[:2]:
                print(x['url'][-50:],'|',c[max(0,m.start()-w//3):m.start()+w].replace("\n"," "))
